	let diffuseColor = s.albedo * select( 1.0 - s.metalness, 1.0 - max( max( authoredF0.x, authoredF0.y ), authoredF0.z ), useSpecular );
	let specF0 = select( mix( vec3f( 0.04 ) * s.specularIntensity, s.albedo, s.metalness ), authoredF0, useSpecular );
	let specF90 = mix( s.specularIntensity, 1.0, s.metalness );
